-- Reports are generated by the API: they can now fail (with a short reason) and be retried.
DO $$
DECLARE c TEXT;
BEGIN
    SELECT conname INTO c FROM pg_constraint
    WHERE conrelid = 'report'::regclass AND contype = 'c' AND pg_get_constraintdef(oid) LIKE '%GENERATING%';
    IF c IS NOT NULL THEN
        EXECUTE format('ALTER TABLE report DROP CONSTRAINT %I', c);
    END IF;
END $$;

ALTER TABLE report
    ADD COLUMN error      VARCHAR(200),
    ADD COLUMN attempts   INT         NOT NULL DEFAULT 0,
    ADD COLUMN started_at TIMESTAMPTZ,
    ADD COLUMN ai_used    BOOLEAN     NOT NULL DEFAULT false,
    ADD CONSTRAINT report_ready_has_content CHECK (status <> 'READY' OR content IS NOT NULL);

CREATE INDEX report_generating_idx ON report (generated_at) WHERE status = 'GENERATING';
